function brand(){document.title='Multiverse Arena v0.9.7.7.2 — Owner Board';document.querySelectorAll('.brand .tag').forEach(x=>x.textContent='v0.9.7.7.2');const u=document.getElementById('updates');if(u)u.textContent='UPDATE LOG  •  v0.9.7.7.2';const latest=document.querySelector('.latest-stat');if(latest){const b=latest.querySelector('b'),s=latest.querySelector('span');if(b)b.textContent='v0.9.7.7.2';if(s)s.textContent='Owner Board • Local Admin Controls'}const h=document.querySelector('.build-health b');if(h)h.textContent='v0.9.7.7.2 • OWNER BOARD • STABLE';const c=document.querySelector('#deviceChooser .eyebrow');if(c)c.textContent='MULTIVERSE ARENA • v0.9.7.7.2'}
